//! Internationalization — JakShell hỗ trợ vi / en / kr / jp / cn / th.
//!
//! Triết lý: chỉ dịch phần PROSE (chào, lời nhắc, label) sang ngôn ngữ địa phương.
//! Mọi thuật ngữ dev (PID, owner, permissions, branch, commit, stash, glob,
//! regex, file, dir, alias, env, …) GIỮ NGUYÊN tiếng Anh để khớp với tài liệu
//! và phản xạ của developer worldwide.

use std::sync::atomic::{AtomicU8, Ordering};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum Lang {
    Vi = 0,
    En = 1,
    Kr = 2,
    Jp = 3,
    Cn = 4,
    Th = 5,
}

static CURRENT: AtomicU8 = AtomicU8::new(0);

impl Lang {
    /// Parse mã ngôn ngữ (chấp nhận nhiều bí danh thông dụng).
    pub fn from_code(s: &str) -> Option<Lang> {
        match s.to_lowercase().as_str() {
            "vi" | "vn" | "viet" | "vietnamese" | "tieng-viet" => Some(Lang::Vi),
            "en" | "us" | "uk" | "english" => Some(Lang::En),
            "kr" | "ko" | "korea" | "korean" | "hangul" => Some(Lang::Kr),
            "jp" | "ja" | "japan" | "japanese" => Some(Lang::Jp),
            "cn" | "zh" | "china" | "chinese" | "mandarin" => Some(Lang::Cn),
            "th" | "thai" | "thailand" => Some(Lang::Th),
            _ => None,
        }
    }

    pub fn code(self) -> &'static str {
        match self {
            Lang::Vi => "vi",
            Lang::En => "en",
            Lang::Kr => "kr",
            Lang::Jp => "jp",
            Lang::Cn => "cn",
            Lang::Th => "th",
        }
    }

    pub fn native(self) -> &'static str {
        match self {
            Lang::Vi => "Tiếng Việt",
            Lang::En => "English",
            Lang::Kr => "한국어",
            Lang::Jp => "日本語",
            Lang::Cn => "中文",
            Lang::Th => "ภาษาไทย",
        }
    }

    pub fn flag(self) -> &'static str {
        match self {
            Lang::Vi => "🇻🇳",
            Lang::En => "🇺🇸",
            Lang::Kr => "🇰🇷",
            Lang::Jp => "🇯🇵",
            Lang::Cn => "🇨🇳",
            Lang::Th => "🇹🇭",
        }
    }

    fn from_u8(n: u8) -> Lang {
        match n {
            1 => Lang::En,
            2 => Lang::Kr,
            3 => Lang::Jp,
            4 => Lang::Cn,
            5 => Lang::Th,
            _ => Lang::Vi,
        }
    }
}

pub const ALL: &[Lang] = &[Lang::Vi, Lang::En, Lang::Kr, Lang::Jp, Lang::Cn, Lang::Th];

pub fn current() -> Lang {
    Lang::from_u8(CURRENT.load(Ordering::Relaxed))
}

pub fn set(lang: Lang) {
    CURRENT.store(lang as u8, Ordering::Relaxed);
}

