/// Helper chọn 1 trong 6 chuỗi theo `Lang`.
#[inline]
fn tr(lang: Lang, arr: [&'static str; 6]) -> &'static str {
    arr[lang as usize]
}

// ─── Persistence ──────────────────────────────────────────────────────────────

pub fn lang_file() -> std::path::PathBuf {
    dirs::home_dir()
        .map(|h| h.join(".config").join("jaksh").join("language"))
        .unwrap_or_else(|| std::path::PathBuf::from("language"))
}

pub fn load_from_disk() {
    if let Ok(content) = std::fs::read_to_string(lang_file()) {
        if let Some(l) = Lang::from_code(content.trim()) {
            set(l);
        }
    }
}

pub fn save_to_disk(lang: Lang) -> std::io::Result<()> {
    let path = lang_file();
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).ok();
    }
    std::fs::write(&path, lang.code())
}

pub fn delete_saved() -> std::io::Result<()> {
    let path = lang_file();
    if path.exists() {
        std::fs::remove_file(&path)?;
    }
    Ok(())
}
